class AsyncTierlistApi(AsyncKonApi):
    """kon-tierlist

    Tier lists editoriales con diff entre versiones, y listas personales compartibles
    """

    kon = "kon-tierlist"

    async def abrir_codigo(self, *, code: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[AbrirCodigoResult]:
        """Open a shared tier list code

        Decodes a share code into the template it came from and the grouped view of that placement (stale items dropped). 400 if the code is unreadable, 404 if its template is gone or not visible to you.

        REST: `GET /api/tierlist/decode/{code}` · scope `kon:tierlist:abrir-codigo`
        idempotent (safe to retry) · MCP tool `tierlist__abrir-codigo`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            code: Share code of a personal tier list
        """
        return await self._call(OPERATIONS["abrir-codigo"], {"code": code}, None, request_options)

    async def anadir_elementos(self, *, slug: Union[str, int], body: AnadirElementosBody, request_options: Optional[RequestOptions] = None) -> Outcome[AnadirElementosResult]:
        """Add items to a template

        Appends hand-written items (1-200) to the template, unranked. The resulting list is validated (422 with `issues`, e.g. a repeated id). Items without `sourceRef` count as hand-added: a later sync asks for `confirm` before dropping them.

        REST: `POST /api/tierlist/templates/{slug}/items` · scope `kon:tierlist:anadir-elementos`
        not idempotent (an Idempotency-Key is sent automatically) · MCP tool `tierlist__anadir-elementos`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug
        """
        return await self._call(OPERATIONS["anadir-elementos"], {"slug": slug}, body, request_options)

    async def bifurcar_plantilla(self, *, slug: Union[str, int], body: BifurcarPlantillaBody, request_options: Optional[RequestOptions] = None) -> Outcome[BifurcarPlantillaResult]:
        """Fork a template into a personal tier list

        Creates your own tier list from a template (a copy, not a reference: republishing the template does not change it), with an optional starting placement or the share `code` of another personal list (stale items are dropped). Returns the new list and its share code. Any signed-in person; an agent needs tierlist:create.

        REST: `POST /api/tierlist/templates/{slug}/fork` · scope `kon:tierlist:bifurcar-plantilla`
        not idempotent (an Idempotency-Key is sent automatically) · MCP tool `tierlist__bifurcar-plantilla`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug
        """
        return await self._call(OPERATIONS["bifurcar-plantilla"], {"slug": slug}, body, request_options)

    async def colocar_en_mi_lista(self, *, id: Union[str, int], body: ColocarEnMiListaBody, request_options: Optional[RequestOptions] = None) -> Outcome[ColocarEnMiListaResult]:
        """Place an item in your personal tier list

        Moves one item of your personal list to a tier (`tierId: null` = unranked) and returns the list with its updated share code. Someone else's list is a 404.

        REST: `POST /api/tierlist/mine/{id}/place` · scope `kon:tierlist:colocar-en-mi-lista`
        idempotent (safe to retry) · MCP tool `tierlist__colocar-en-mi-lista`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            id: Personal tier list id
        """
        return await self._call(OPERATIONS["colocar-en-mi-lista"], {"id": id}, body, request_options)

    async def colocar_en_plantilla(self, *, slug: Union[str, int], body: ColocarEnMiListaBody, request_options: Optional[RequestOptions] = None) -> Outcome[ColocarEnPlantillaResult]:
        """Place an item in a template tier

        Moves one item of the template to a tier (`tierId: null` sends it back to the unranked pool) and returns the updated template. 409 if the item or the tier does not exist. Admin/editor, or an agent with tierlist:update.

        REST: `POST /api/tierlist/templates/{slug}/place` · scope `kon:tierlist:colocar-en-plantilla`
        idempotent (safe to retry) · MCP tool `tierlist__colocar-en-plantilla`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug
        """
        return await self._call(OPERATIONS["colocar-en-plantilla"], {"slug": slug}, body, request_options)

    async def comparar_versiones(self, *, slug: Union[str, int], other_id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[CompararVersionesResult]:
        """Diff a template against another version

        Compares the template `slug` (after) with the tier list `otherId` (before): promoted, demoted, added and removed items with their from/to tiers, plus the unchanged count. Ready to write a 'tier list update' post. A personal list you cannot see is a 404.

        REST: `GET /api/tierlist/templates/{slug}/diff/{otherId}` · scope `kon:tierlist:comparar-versiones`
        idempotent (safe to retry) · MCP tool `tierlist__comparar-versiones`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug (the newer version)
            other_id: Id of the tier list to compare against (the older version)
        """
        return await self._call(OPERATIONS["comparar-versiones"], {"slug": slug, "otherId": other_id}, None, request_options)

    async def listar_plantillas(self, *, request_options: Optional[RequestOptions] = None) -> Outcome[ListarPlantillasResult]:
        """List tier list templates

        Every editorial template (the site's published tier lists), most recently updated first: id, slug, title and version. Use the slug to read, place, sync or fork one.

        REST: `GET /api/tierlist/templates` · scope `kon:tierlist:listar-plantillas`
        idempotent (safe to retry) · MCP tool `tierlist__listar-plantillas`
        Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["listar-plantillas"], {}, None, request_options)

    async def publicar_plantilla(self, *, body: PublicarPlantillaBody, request_options: Optional[RequestOptions] = None) -> Outcome[PublicarPlantillaResult]:
        """Create or rewrite a tier list template

        Upsert by slug: 201 when it creates the template, 200 when it rewrites it. Omitted tiers/items/placement keep the current ones (a new template starts with the S-D tiers). The whole list is validated before saving (422 with `issues`). Admin/editor, or an agent with tierlist:publish. To move one item use place, to add items use add-items: a full PUT overwrites whatever another editor changed meanwhile.

        REST: `PUT /api/tierlist/templates` · scope `kon:tierlist:publicar-plantilla`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `tierlist__publicar-plantilla`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["publicar-plantilla"], {}, body, request_options)

    async def quitar_elemento(self, *, slug: Union[str, int], item_id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[QuitarElementoResult]:
        """Remove an item from a template

        Removes the item and its placement from the template and returns the updated template. 404 if the template or the item does not exist.

        REST: `DELETE /api/tierlist/templates/{slug}/items/{itemId}` · scope `kon:tierlist:quitar-elemento`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `tierlist__quitar-elemento`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["quitar-elemento"], {"slug": slug, "itemId": item_id}, None, request_options)

    async def sincronizar_catalogo(self, *, slug: Union[str, int], body: Optional[SincronizarCatalogoBody] = None, request_options: Optional[RequestOptions] = None) -> Outcome[SincronizarCatalogoResult]:
        """Sync a template with its catalog

        Makes the template's items equal to a catalog: `catalog` (items in the body), else `datasetId` (sync against that dataset and pin it), else the dataset already pinned (call with no body). New items enter unranked, retired ones leave with their placement, existing placements are kept. If hand-added items would be lost it answers 409 with `perdidos`: repeat with `confirm: true`. Returns the template, the unranked count, the catalog size (`enElCatalogo`) and `origen` (dataset and image field used).

        REST: `POST /api/tierlist/templates/{slug}/sync` · scope `kon:tierlist:sincronizar-catalogo`
        not idempotent (an Idempotency-Key is sent automatically) · sensitive: may come back as a proposal pending human approval · MCP tool `tierlist__sincronizar-catalogo`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug
        """
        return await self._call(OPERATIONS["sincronizar-catalogo"], {"slug": slug}, body, request_options)

    async def ver_plantilla(self, *, slug: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[VerPlantillaResult]:
        """Read a tier list template

        The template row (tiers, items, placement) plus `view`: the items already grouped by tier, in display order, with the unranked pool apart.

        REST: `GET /api/tierlist/templates/{slug}` · scope `kon:tierlist:ver-plantilla`
        idempotent (safe to retry) · MCP tool `tierlist__ver-plantilla`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Template slug
        """
        return await self._call(OPERATIONS["ver-plantilla"], {"slug": slug}, None, request_options)
